/**
Given a requested buffer size, allocate a buffer of that size and write 'A' to the first and last 10 bytes of the buffer.

@param buf_size: the size of the buffer to allocate
@return the allocated buffer
*/
char* allocate_buffer_and_write(size_t buf_size) {
    // Allocate the buffer of the requested size.
    char* buffer = (char*)malloc(buf_size);

    // If malloc failed to allocate memory, return NULL.
    if (buffer == NULL) {
        return NULL;
    }

    // If the buffer size is 0, there are no bytes to write to.
    // In this case, we simply return the allocated (zero-sized) buffer.
    // Note: malloc(0) might return a non-NULL pointer that can be freed.
    if (buf_size == 0) {
        return buffer;
    }

    // Write 'A' to the first 10 bytes of the buffer.
    // If buf_size is less than 10, write 'A' to all available bytes (i.e., buf_size bytes).
    size_t bytes_for_first_part = (buf_size < 10) ? buf_size : 10;
    memset(buffer, 'A', bytes_for_first_part);

    // Write 'A' to the last 10 bytes of the buffer.
    // This operation is only performed if the buffer has more than 10 bytes.
    // If buf_size is 10 or less, the entire buffer is already covered by the first memset,
    // or there aren't 10 bytes to constitute a "last 10 bytes" distinct from the "first 10 bytes".
    if (buf_size > 10) {
        // Calculate the starting address for the last 10 bytes.
        // This is (buf_size - 10) bytes from the beginning of the buffer.
        // The condition buf_size > 10 ensures (buf_size - 10) does not underflow.
        char* last_10_bytes_start = buffer + (buf_size - 10);
        memset(last_10_bytes_start, 'A', 10);
    }

    // Return the pointer to the allocated buffer.
    return buffer;
}
